from pathlib import Path
path = Path('/home/trajan/Projects/ema/apps/renderer/src/components/hq/HQApp.tsx')
text = path.read_text()
text = text.replace("type GoalRecord = {\n  readonly id: string;\n  readonly title: string;\n  readonly status: string;\n  readonly timeframe: string;\n  readonly project_id: string | null;\n  readonly space_id: string | null;\n  readonly intent_slug: string | null;\n  readonly target_date: string | null;\n};\n", "type GoalRecord = {\n  readonly id: string;\n  readonly title: string;\n  readonly status: string;\n  readonly timeframe: string;\n  readonly project_id: string | null;\n  readonly space_id: string | null;\n  readonly intent_slug: string | null;\n  readonly target_date: string | null;\n  readonly updated_at?: string;\n};\n")
insert = '''\ntype ReviewSourceLink = {\n  readonly source_kind: string;\n  readonly chronicle_session_id: string;\n  readonly chronicle_entry_id: string | null;\n  readonly chronicle_artifact_id: string | null;\n};\n\ntype RuntimeProvenanceRecord = {\n  readonly lookup: {\n    readonly target_kind: "intent" | "goal" | "calendar_entry" | "execution";\n    readonly target_id: string;\n  };\n  readonly receipt: {\n    readonly id: string;\n    readonly review_item_id: string;\n    readonly target_kind: string;\n    readonly target_id: string | null;\n    readonly promotion_mode: string;\n    readonly provenance_summary: string | null;\n    readonly inserted_at: string;\n  } | null;\n  readonly review_item: {\n    readonly id: string;\n    readonly title: string;\n    readonly status: string;\n    readonly candidate_kind: string;\n    readonly confidence: number | null;\n    readonly summary: string | null;\n    readonly source_excerpt: string | null;\n    readonly updated_at: string;\n  } | null;\n  readonly extraction: {\n    readonly id: string;\n    readonly title: string;\n    readonly kind: string;\n    readonly source_excerpt: string | null;\n    readonly confidence: number | null;\n    readonly updated_at: string;\n  } | null;\n  readonly source: ReviewSourceLink | null;\n  readonly chronicle: {\n    readonly session: {\n      readonly id: string;\n      readonly title: string;\n      readonly summary: string | null;\n      readonly imported_at: string;\n    };\n    readonly entry: {\n      readonly id: string;\n      readonly ordinal: number;\n      readonly role: string;\n      readonly content: string;\n      readonly occurred_at: string | null;\n    } | null;\n    readonly artifact: {\n      readonly id: string;\n      readonly kind: string;\n      readonly name: string;\n      readonly original_path: string | null;\n      readonly stored_path: string;\n    } | null;\n  } | null;\n  readonly lineage_metadata: Record<string, unknown>;\n};\n\ntype GoalProvenanceBundle = {\n  readonly goal: GoalRecord;\n  readonly provenance: RuntimeProvenanceRecord | null;\n};\n'''
text = text.replace("type IntentNode = {\n", insert + "\ntype IntentNode = {\n")
text = text.replace("function titleForChronicle(session: ChronicleSessionRecord): string {\n  return session.title || session.source_label || session.source_kind || `Session ${session.id.slice(0, 8)}`;\n}\n", "function titleForChronicle(session: ChronicleSessionRecord): string {\n  return session.title || session.source_label || session.source_kind || `Session ${session.id.slice(0, 8)}`;\n}\n\nfunction describeConfidence(value: number | null | undefined): string {\n  if (typeof value !== \"number\") return \"unscored\";\n  return `${Math.round(value * 100)}% confidence`;\n}\n\nfunction humanizeCandidateKind(value: string): string {\n  return value.replace(/_/g, \" \" );\n}\n\nfunction summariseLineage(metadata: Record<string, unknown>): string[] {\n  const details: string[] = [];\n  const executionId = typeof metadata.execution_id === \"string\" ? metadata.execution_id : null;\n  const intentSlug = typeof metadata.intent_slug === \"string\" ? metadata.intent_slug : null;\n  const projectId = typeof metadata.project_id === \"string\" ? metadata.project_id : null;\n  const reviewItemId = typeof metadata.chronicle_review_item_id === \"string\" ? metadata.chronicle_review_item_id : null;\n\n  if (intentSlug) details.push(`intent ${intentSlug}`);\n  if (executionId) details.push(`execution ${executionId.slice(0, 8)}`);\n  if (projectId) details.push(`project ${projectId.slice(0, 8)}`);\n  if (reviewItemId) details.push(`review item ${reviewItemId.slice(0, 8)}`);\n\n  return details;\n}\n")
text = text.replace("  const [chronicleSessions, setChronicleSessions] = useState<ChronicleSessionRecord[]>([]);\n  const [intentTree, setIntentTree] = useState<IntentNode[]>([]);\n", "  const [chronicleSessions, setChronicleSessions] = useState<ChronicleSessionRecord[]>([]);\n  const [goalProvenance, setGoalProvenance] = useState<GoalProvenanceBundle[]>([]);\n  const [intentTree, setIntentTree] = useState<IntentNode[]>([]);\n")
old = "        setGoals(goalsData.goals ?? []);\n        setProposals(proposalsData.proposals ?? []);\n        setExecutions(executionsData.executions ?? []);\n        setChronicleSessions(chronicleData.sessions ?? []);\n        setIntentTree(intentsData.tree ?? []);\n"
new = '''        const nextGoals = goalsData.goals ?? [];\n        setGoals(nextGoals);\n        setProposals(proposalsData.proposals ?? []);\n        setExecutions(executionsData.executions ?? []);\n        setChronicleSessions(chronicleData.sessions ?? []);\n        setIntentTree(intentsData.tree ?? []);\n        const provenanceGoals = nextGoals\n          .filter((goal) => goal.status === "active")\n          .sort((left, right) => String(right.updated_at ?? right.target_date ?? "").localeCompare(String(left.updated_at ?? left.target_date ?? "")))\n          .slice(0, 6);\n        const provenancePairs = await Promise.all(provenanceGoals.map(async (goal) => {\n          try {\n            const response = await api.get<{ provenance: RuntimeProvenanceRecord }>(`/review/provenance?target_kind=goal&target_id=${encodeURIComponent(goal.id)}`);\n            return { goal, provenance: response.provenance ?? null } satisfies GoalProvenanceBundle;\n          } catch {\n            return { goal, provenance: null } satisfies GoalProvenanceBundle;\n          }\n        }));\n        setGoalProvenance(provenancePairs);\n'''
text = text.replace(old, new)
anchor = "  const scopedIntents = selectedProject\n    ? activeIntents.filter((intent) => intent.project_id === selectedProject.id)\n    : activeIntents;\n"
addition = '''  const scopedGoalProvenance = useMemo(() => (\n    selectedProject\n      ? goalProvenance.filter(({ goal }) => goal.project_id === selectedProject.id)\n      : goalProvenance\n  ), [goalProvenance, selectedProject]);\n  const provenanceCoverageCount = scopedGoalProvenance.filter(({ provenance }) => provenance?.receipt || provenance?.review_item || provenance?.chronicle).length;\n  const selectedGoalProvenance = scopedGoalProvenance[0] ?? null;\n'''
text = text.replace(anchor, anchor + addition)
needle = '            <Panel eyebrow="Chronicle Ingress" title="Recent sessions that should become durable memory or work" actionLabel="Open Operator Chat" onAction={() => void openApp("operator-chat")}>\n'
insert_panel = '''            <Panel eyebrow="Provenance Workbench" title="See which active goals still carry real Chronicle + Review lineage" actionLabel="Open Goals" onAction={() => void openApp("goals")}>\n              {loading ? <EmptyState label="Loading provenance coverage..." /> : scopedGoalProvenance.length === 0 ? <EmptyState label="No active goals in scope yet, so there is no goal-level provenance thread to inspect." /> : (\n                <div style={{ display: "grid", gap: 12 }}>\n                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>\n                    <MetricCard label="Goals in scope" value={String(scopedGoalProvenance.length)} detail="Active goals checked for provenance" tone="#34d399" compact />\n                    <MetricCard label="With lineage" value={String(provenanceCoverageCount)} detail="Goals linked back to Chronicle/Review" tone={provenanceCoverageCount > 0 ? "#60a5fa" : "#94a3b8"} compact />\n                  </div>\n\n                  <div style={{ display: "grid", gap: 8 }}>\n                    {scopedGoalProvenance.map(({ goal, provenance }) => {\n                      const hasLineage = Boolean(provenance?.receipt || provenance?.review_item || provenance?.chronicle);\n                      const receiptMeta = provenance?.receipt\n                        ? `${provenance.receipt.promotion_mode} · ${formatAgo(provenance.receipt.inserted_at)}`\n                        : "not promoted from Review yet";\n                      return (\n                        <ListRow\n                          key={goal.id}\n                          title={goal.title}\n                          subtitle={hasLineage ? receiptMeta : "Active goal exists, but HQ cannot yet trace a Chronicle/Review receipt for it."}\n                          meta={hasLineage ? "lineage" : "gap"}\n                          highlighted={selectedGoalProvenance?.goal.id === goal.id}\n                          onClick={() => void openGoal(goal)}\n                        />\n                      );\n                    })}\n                  </div>\n\n                  {selectedGoalProvenance ? (\n                    <div style={{ borderRadius: 18, padding: "14px 16px", border: "1px solid rgba(255,255,255,0.06)", background: "rgba(6,8,14,0.34)", display: "grid", gap: 10 }}>\n                      <div>\n                        <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: "0.16em", color: "var(--pn-text-muted)", fontWeight: 700 }}>Focused provenance thread</div>\n                        <div style={{ marginTop: 8, color: "rgba(255,255,255,0.94)", fontSize: 16, fontWeight: 650 }}>{selectedGoalProvenance.goal.title}</div>\n                        <div style={{ marginTop: 4, color: "var(--pn-text-secondary)", fontSize: 12, lineHeight: 1.6 }}>\n                          {selectedGoalProvenance.provenance?.receipt?.provenance_summary\n                            || selectedGoalProvenance.provenance?.review_item?.summary\n                            || "This goal is active, but provenance is still missing or only partially attached in the backend."}\n                        </div>\n                      </div>\n\n                      {selectedGoalProvenance.provenance?.chronicle ? (\n                        <div style={{ display: "grid", gap: 8 }}>\n                          <MiniDivider label="Chronicle source" />\n                          <ListRow\n                            title={selectedGoalProvenance.provenance.chronicle.session.title}\n                            subtitle={selectedGoalProvenance.provenance.chronicle.entry?.content\n                              || selectedGoalProvenance.provenance.chronicle.session.summary\n                              || "Chronicle session imported without a summary excerpt."}\n                            meta={formatAgo(selectedGoalProvenance.provenance.chronicle.session.imported_at)}\n                          />\n                        </div>\n                      ) : null}\n\n                      {selectedGoalProvenance.provenance?.review_item ? (\n                        <div style={{ display: "grid", gap: 8 }}>\n                          <MiniDivider label="Review decision" />\n                          <ListRow\n                            title={selectedGoalProvenance.provenance.review_item.title}\n                            subtitle={`${humanizeCandidateKind(selectedGoalProvenance.provenance.review_item.candidate_kind)} · ${describeConfidence(selectedGoalProvenance.provenance.review_item.confidence)}${selectedGoalProvenance.provenance.review_item.source_excerpt ? ` · ${selectedGoalProvenance.provenance.review_item.source_excerpt}` : ""}`}\n                            meta={selectedGoalProvenance.provenance.review_item.status}\n                          />\n                        </div>\n                      ) : null}\n\n                      {summariseLineage(selectedGoalProvenance.provenance?.lineage_metadata ?? {}).length > 0 ? (\n                        <div style={{ display: "grid", gap: 8 }}>\n                          <MiniDivider label="Cross-object pivots" />\n                          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>\n                            {typeof selectedGoalProvenance.provenance?.lineage_metadata.intent_slug === "string" ? (\n                              <ActionButton label="Intent thread" note={String(selectedGoalProvenance.provenance.lineage_metadata.intent_slug)} onClick={() => void openApp("intent-schematic", null, { searchParams: { intent: String(selectedGoalProvenance.provenance?.lineage_metadata.intent_slug) } })} />\n                            ) : null}\n                            {typeof selectedGoalProvenance.provenance?.lineage_metadata.execution_id === "string" ? (\n                              <ActionButton label="Execution" note={String(selectedGoalProvenance.provenance.lineage_metadata.execution_id).slice(0, 8)} onClick={() => void openApp("executions", null, { searchParams: { execution: String(selectedGoalProvenance.provenance?.lineage_metadata.execution_id) } })} />\n                            ) : null}\n                            <ActionButton label="Goal record" note={selectedGoalProvenance.goal.timeframe} onClick={() => void openGoal(selectedGoalProvenance.goal)} />\n                          </div>\n                        </div>\n                      ) : (\n                        <div style={{ color: "var(--pn-text-muted)", fontSize: 12, lineHeight: 1.6 }}>\n                          No downstream intent or execution pivots are attached to this goal lineage yet. That is a real backend gap, not a hidden UI failure.\n                        </div>\n                      )}\n                    </div>\n                  ) : null}\n                </div>\n              )}\n            </Panel>\n\n'''
text = text.replace(needle, insert_panel + needle)
path.write_text(text)
